INSERT INTO reglamento_grupo (grupo_id, version, contenido, hash_contenido, clausulas_mora, clausulas_abandono, vigente_desde, redactado_por) VALUES
  ((SELECT id FROM grupo WHERE codigo_publico = 'GRP-DEMO-01'), 1, 'Reglamento del grupo demo. Aporte mensual de Bs 500 con vencimiento el día 10. Tres días de gracia. Recargo del 2 % sobre el aporte, con tope del 100 %. El fondo de garantía se constituye con Bs 100 por participante al inicio y cubre el aporte impago a partir del quinto día de mora, generando una deuda a nombre de quien no pagó. El orden de turnos se define por sorteo con semilla verificable.', encode(digest('reglamento-grupo-demo-v1', 'sha256'), 'hex'), 'Recargo del 2 % sobre el aporte impago, con tope del 100 % del aporte. La gracia es de 3 días corridos desde el vencimiento.', 'El cupo se libera y se busca reemplazo. La deuda no se extingue con la salida del grupo.', now() - interval '45 days', (SELECT id FROM usuario WHERE codigo_publico = 'USR000001'))
